// app/blog/[slug]/page.tsx
import { notFound } from "next/navigation";

const posts = [
  { slug: "primeiro-post", titulo: "Meu primeiro post" },
  { slug: "novidades", titulo: "Novidades do Next.js" },
];

export default async function Post({
  params,
}: {
  params: Promise<{ slug: string }>;
}) {
  const { slug } = await params;
  const post = posts.find((p) => p.slug === slug);

  if (!post) notFound();   // mostra a pagina 404 (secao 4.11)

  return <h1>{post.titulo}</h1>;
}

// app/loja/[categoria]/[id]/page.tsx -- dois segmentos
export default async function Produto({
  params,
}: {
  params: Promise<{ categoria: string; id: string }>;
}) {
  const { categoria, id } = await params;
  return <p>{categoria} / {id}</p>;   // /loja/eletronicos/notebook
}

// app/docs/[...partes]/page.tsx -- captura varios niveis
export default async function Docs({
  params,
}: {
  params: Promise<{ partes: string[] }>;
}) {
  const { partes } = await params;   // /docs/a/b -> ["a", "b"]
  return <p>{partes.join(" / ")}</p>;
}

