"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";

const links = [
  { href: "/", rotulo: "Inicio" },
  { href: "/projetos", rotulo: "Projetos" },
  { href: "/contato", rotulo: "Contato" },
];

export default function Menu() {
  const caminho = usePathname();   // ex.: "/projetos"

  return (
    <nav>
      {links.map((link) => (
        <Link
          key={link.href}
          href={link.href}
          className={caminho === link.href ? "ativo" : ""}
        >
          {link.rotulo}
        </Link>
      ))}
    </nav>
  );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";

export default function CaixaBusca() {
  const router = useRouter();
  const [termo, setTermo] = useState("");

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        router.push(`/busca?q=${encodeURIComponent(termo)}`);
      }}
    >
      <input value={termo} onChange={(e) => setTermo(e.target.value)} />
      <button type="submit">Buscar</button>
      <button type="button" onClick={() => router.back()}>
        Voltar
      </button>
    </form>
  );
}

// app/busca/page.tsx -- Server Component
export default async function Busca({
  searchParams,
}: {
  searchParams: Promise<{ q?: string }>;
}) {
  const { q } = await searchParams;   // /busca?q=next -> "next"
  return <h1>Resultados para: {q ?? "(nada)"}</h1>;
}

// app/loading.tsx
export default function Carregando() {
  return <p>Carregando...</p>;
}

// app/error.tsx
"use client";   // obrigatorio no error.tsx

export default function ErroPagina({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  return (
    <div>
      <h2>Algo deu errado!</h2>
      <p>{error.message}</p>
      <button onClick={() => reset()}>Tentar novamente</button>
    </div>
  );
}

// app/not-found.tsx
import Link from "next/link";

export default function NaoEncontrada() {
  return (
    <div>
      <h1>404 -- Pagina nao encontrada</h1>
      <Link href="/">Voltar para o inicio</Link>
    </div>
  );
}

// app/layout.tsx
import type { Metadata } from "next";
import "./globals.css";

export const metadata: Metadata = {
  title: {
    template: "%s | Meu Portfolio",   // %s = titulo de cada pagina
    default: "Meu Portfolio",         // quando a pagina nao define
  },
  description: "Projetos e estudos de desenvolvimento web",
};

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <html lang="pt-BR">
      <body>{children}</body>
    </html>
  );
}

// app/projetos/page.tsx
import type { Metadata } from "next";

export const metadata: Metadata = {
