  description: "Lista dos meus projetos",
  openGraph: {
    title: "Projetos",
    images: ["/capa-projetos.png"],   // previa ao compartilhar
  },
};

export default function Projetos() {
  return <h1>Projetos</h1>;
}

// app/blog/[slug]/page.tsx (junto com o componente Post)
import type { Metadata } from "next";

export async function generateMetadata({
  params,
}: {
  params: Promise<{ slug: string }>;
}): Promise<Metadata> {
  const { slug } = await params;
  const post = posts.find((p) => p.slug === slug);
  return { title: post?.titulo ?? "Post nao encontrado" };
}
